function validate([expression]) {
  if (typeof expression !== 'string' || !/^-?\d+\/\d+([+-]\d+\/\d+)*$/.test(expression)) return 'expression must look like "a/b+c/d-e/f" (no leading +).';
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const parts = expression.match(/\d+\/\d+/g);
  if (parts.length > 10) return 'expression has at most 10 fractions.';
  for (const part of parts) {
    const [p, q] = part.split('/').map(Number);
    if (p < 1 || p > 10 || q < 1 || q > 10) return 'Each numerator and denominator is between 1 and 10.';
    if (gcd(p, q) !== 1) return 'Each fraction must be irreducible.';
    if (/^0\d/.test(part) || /\/0\d/.test(part)) return 'Numbers have no leading zeros.';
  }
  return null;
}

