function fractionAddition(expression) {
  // Put everything over 2520 = lcm(1..10), then reduce by trial division.
  const parts = expression.match(/[+-]?\d+\/\d+/g);
  let total = 0;
  for (const part of parts) {
    const [p, q] = part.split('/').map(Number);
    total += p * (2520 / q);
  }
  let q = 2520;
  for (let d = 2; d <= q; d++) {
    while (q % d === 0 && total % d === 0) {
      total /= d;
      q /= d;
    }
  }
  if (total === 0) return '0/1';
  return total + '/' + q;
}

