function generate(rand, size) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const count = size === 'large' ? 10 : 1 + Math.floor(rand() * 4);
  const small = size === 'small' && rand() < 0.5;
  let expression = '';
  for (let k = 0; k < count; k++) {
    let p, q;
    do {
      p = 1 + Math.floor(rand() * (small ? 4 : 10));
      q = 1 + Math.floor(rand() * (small ? 4 : 10));
    } while (gcd(p, q) !== 1);
    const negative = rand() < 0.5;
    if (k === 0) expression += (negative ? '-' : '') + p + '/' + q;
    else expression += (negative ? '-' : '+') + p + '/' + q;
  }
  return [expression];
}
